// Legacy adoption acceptance test: every fixture in fixtures/ (generated by
// make_fixtures.sh from the 2.5.0 sources) must dump IDENTICALLY under 3.0 —
// same column names, same stats, same records in the same order — and then
// keep working: new writes go to a segment, and the window slides over the
// adopted records one by one. Then each fixture is converted to segments
// (tsdb_maintain until done) and must still dump identically, before and
// after a reopen, with nothing of the 2.x file left.
#include "esp_tsdb.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>

static int fails = 0;
#define CHECK(cond, msg) do { int _ok = (cond); \
    printf("  [%-44s] %s\n", msg, _ok ? "PASS" : "FAIL"); if (!_ok) fails++; } while (0)

static char *slurp(const char *p, long *len) {
    FILE *f = fopen(p, "rb"); if (!f) return NULL;
    fseek(f, 0, SEEK_END); long n = ftell(f); fseek(f, 0, SEEK_SET);
    char *b = malloc(n + 1); fread(b, 1, n, f); b[n] = 0; fclose(f); if (len) *len = n; return b;
}

static void copy(const char *src, const char *dst) {
    long n; char *b = slurp(src, &n); if (!b) { remove(dst); return; }
    FILE *f = fopen(dst, "wb"); fwrite(b, 1, n, f); fclose(f); free(b);
}

static void dump(tsdb_t *db, const char *out) {
    FILE *f = fopen(out, "w");
    uint8_t total = tsdb_get_total_params_h(db);
    fprintf(f, "columns:");
    for (uint8_t i = 0; i < total; i++) { const char *n = tsdb_get_param_name_h(db, i); fprintf(f, "%s%s", i ? "," : "", n ? n : ""); }
    fprintf(f, "\n");
    tsdb_stats_t s; tsdb_get_stats_h(db, &s);
    fprintf(f, "stats: records=%u max=%u oldest=%u newest=%u writes=%u evictions=%u params=%u extras=%u\n",
            s.total_records, s.max_records, s.oldest_timestamp, s.newest_timestamp,
            s.total_writes, s.total_evictions, s.num_params, s.extra_params);
    tsdb_query_t q; tsdb_query_init_h(db, &q, 0, UINT32_MAX, NULL, 0);
    uint32_t ts; int16_t v[64];
    while (tsdb_query_next(&q, &ts, v) == ESP_OK) {
        fprintf(f, "%u", ts);
        for (uint8_t i = 0; i < total; i++) fprintf(f, ",%d", v[i]);
        fprintf(f, "\n");
    }
    tsdb_query_close(&q);
    fclose(f);
}

static void wipe_all(const char *p) {
    char b[256];
    remove(p);
    snprintf(b, sizeof b, "%s.h0", p); remove(b);
    snprintf(b, sizeof b, "%s.h1", p); remove(b);
    snprintf(b, sizeof b, "%s.mig", p); remove(b);
    snprintf(b, sizeof b, "%s.cv", p); remove(b);
    for (int i = 1; i < 64; i++) { snprintf(b, sizeof b, "%s.s%010d", p, i); remove(b); }
    for (int i = 0; i < 2000; i++) { snprintf(b, sizeof b, "%s.c%010d", p, i); remove(b); }
}

static int exists(const char *p) { struct stat st; return stat(p, &st) == 0; }
static uint64_t low_free(void) { return 10; }
static long fsize(const char *p) { struct stat st; return stat(p, &st) == 0 ? (long) st.st_size : -1; }

typedef struct { const char *name; uint8_t np; const char *names[20]; uint32_t maxrec; } fx_t;

int main(void) {
    static char wb[20][8]; const char *w[20];
    for (int i = 0; i < 20; i++) { snprintf(wb[i], 8, "w%02d", i); w[i] = wb[i]; }
    fx_t fx[] = {
        {"wrapped.tsdb",   3, {"soc", "vbat", "pload"}, 150},
        {"extras.tsdb",    2, {"soc", "vbat"},          1000},
        {"wide.tsdb",     20, {0},                      100},
        {"legacy512.tsdb", 2, {"soc", "vbat"},          100},
        {"sidecar.tsdb",   3, {"soc", "vbat", "pload"}, 500},
        {"unlimited.tsdb", 3, {"soc", "vbat", "pload"}, 0},
        {"partial.tsdb",   3, {"soc", "vbat", "pload"}, 1000},
    };
    for (int i = 0; i < 20; i++) fx[2].names[i] = w[i];

    for (size_t k = 0; k < sizeof fx / sizeof fx[0]; k++) {
        char src[256], exp[256], path[256], out[256], side[256];
        snprintf(src, sizeof src, "fixtures/%s", fx[k].name);
        snprintf(exp, sizeof exp, "fixtures/%s.expected", fx[k].name);
        snprintf(path, sizeof path, "/tmp/lg_%s", fx[k].name);
        snprintf(out, sizeof out, "/tmp/lg_%s.dump", fx[k].name);
        printf("%s\n", fx[k].name);
        wipe_all(path);
        copy(src, path);
        snprintf(side, sizeof side, "%s.h0", src); if (exists(side)) { char d[256]; snprintf(d, sizeof d, "%s.h0", path); copy(side, d); }
        snprintf(side, sizeof side, "%s.h1", src); if (exists(side)) { char d[256]; snprintf(d, sizeof d, "%s.h1", path); copy(side, d); }
        long before = fsize(path);

        tsdb_config_t c = {0};
        c.filepath = path; c.num_params = fx[k].np; c.param_names = fx[k].names;
        c.max_records = fx[k].maxrec; c.buffer_pool_size = 16 * 1024;
        c.alloc_strategy = TSDB_ALLOC_INTERNAL_RAM;
        tsdb_t *db = tsdb_open(&c);
        CHECK(db != NULL, "opens");
        if (!db) continue;

        dump(db, out);
        long la, lb; char *a = slurp(out, &la), *b = slurp(exp, &lb);
        int same = a && b && la == lb && memcmp(a, b, la) == 0;
        CHECK(same, "dump identical to 2.5.0");
        if (!same && a && b) {
            // show first differing line
            char *pa = a, *pb = b; int line = 1;
            while (*pa && *pb) { char *ea = strchr(pa, '\n'), *eb = strchr(pb, '\n'); if (!ea || !eb) break;
                if ((ea - pa) != (eb - pb) || memcmp(pa, pb, ea - pa)) { printf("    line %d:\n      got: %.*s\n      exp: %.*s\n", line, (int)(ea - pa), pa, (int)(eb - pb), pb); break; }
                pa = ea + 1; pb = eb + 1; line++; }
        }
        free(a); free(b);

        // New writes land in a segment; the legacy file is untouched.
        tsdb_stats_t s0; tsdb_get_stats_h(db, &s0);
        uint8_t total = tsdb_get_total_params_h(db);
        int16_t v[64]; for (int i = 0; i < 64; i++) v[i] = (int16_t)(7000 + i);
        uint32_t t1 = s0.newest_timestamp + 10;
        CHECK(tsdb_write_h(db, t1, v) == ESP_OK, "write after adoption");
        CHECK(fsize(path) == before, "legacy file size unchanged");
        char seg1[256]; snprintf(seg1, sizeof seg1, "%s.s%010d", path, 1);
        CHECK(exists(seg1), "segment 1 created");
        tsdb_stats_t s1; tsdb_get_stats_h(db, &s1);
        uint32_t expect_records = (fx[k].maxrec && s0.total_records >= fx[k].maxrec) ? fx[k].maxrec : s0.total_records + 1;
        CHECK(s1.total_records == expect_records && s1.newest_timestamp == t1 &&
              s1.total_writes == s0.total_writes + 1 && s1.segment_count == 2, "stats after write");
        // Read back the new record with all columns.
        tsdb_query_t q; tsdb_query_init_h(db, &q, t1, t1, NULL, 0);
        uint32_t ts; int16_t rv[64]; int ok = tsdb_query_next(&q, &ts, rv) == ESP_OK;
        for (uint8_t i = 0; ok && i < total; i++) ok = (rv[i] == (int16_t)(7000 + i));
        tsdb_query_close(&q);
        CHECK(ok, "new record readable (all columns)");
        // Old + new in one scan, monotonic.
        tsdb_query_init_h(db, &q, 0, UINT32_MAX, NULL, 0);
        uint32_t prev = 0, n = 0; int mono = 1;
        while (tsdb_query_next(&q, &ts, rv) == ESP_OK) { if (n && ts <= prev) mono = 0; prev = ts; n++; }
        tsdb_query_close(&q);
        CHECK(mono && n == s1.total_records && prev == t1, "full scan spans legacy + segment");
        tsdb_close_h(db);

        // Reopen: same picture.
        db = tsdb_open(&c);
        CHECK(db != NULL, "reopen");
        if (db) {
            tsdb_stats_t s2; tsdb_get_stats_h(db, &s2);
            CHECK(s2.total_records == s1.total_records && s2.newest_timestamp == t1 &&
                  s2.total_writes == s1.total_writes, "state persists across reopen");
            tsdb_close_h(db);
        }
    }

    // Legacy eviction: wrapped fixture (150 retained of max 150). Writing 150
    // more must skip the legacy records one by one and unlink the file once
    // every record is past the window.
    printf("legacy eviction\n");
    {
        const char *path = "/tmp/lg_evict.tsdb";
        wipe_all(path);
        copy("fixtures/wrapped.tsdb", path);
        const char *n3[] = {"soc", "vbat", "pload"};
        tsdb_config_t c = {0};
        c.filepath = path; c.num_params = 3; c.param_names = n3; c.max_records = 150;
        c.buffer_pool_size = 16 * 1024; c.alloc_strategy = TSDB_ALLOC_INTERNAL_RAM;
        tsdb_t *db = tsdb_open(&c);
        tsdb_stats_t s; tsdb_get_stats_h(db, &s);
        uint32_t t = s.newest_timestamp;
        int16_t v[3] = {1, 2, 3};
        for (int i = 0; i < 100; i++) { t += 10; tsdb_write_h(db, t, v); }
        tsdb_get_stats_h(db, &s);
        CHECK(s.total_records == 150, "100 writes: window slid");
        uint32_t cnt; tsdb_query_count_h(db, 0, UINT32_MAX, &cnt);
        CHECK(cnt == 150, "count exact at capacity");
        // Oldest visible must be legacy record #100 (0-based) of 150.
        tsdb_query_t q; tsdb_query_init_h(db, &q, 0, UINT32_MAX, NULL, 0);
        uint32_t ts; int16_t rv[3]; tsdb_query_next(&q, &ts, rv); tsdb_query_close(&q);
        CHECK(ts == s.oldest_timestamp, "oldest visible == stats.oldest");
        for (int i = 0; i < 50; i++) { t += 10; tsdb_write_h(db, t, v); }
        tsdb_get_stats_h(db, &s);
        CHECK(s.total_records == 150 && !exists(path), "150 writes: legacy file gone (converted)");
        CHECK(!exists("/tmp/lg_evict.tsdb.cv"), "no conversion marker left");
        CHECK(!exists("/tmp/lg_evict.tsdb.h0") && !exists("/tmp/lg_evict.tsdb.h1"), "sidecars gone with it");
        tsdb_close_h(db);
        db = tsdb_open(&c);
        tsdb_get_stats_h(db, &s);
        CHECK(db && s.total_records == 150 && s.segment_count >= 1, "reopen without legacy");
        tsdb_close_h(db);
    }

    // Conversion: every fixture moved into segments by tsdb_maintain, then
    // dumped again — identical to 2.5.0's dump, before and after a reopen.
    printf("conversion\n");
    for (size_t k = 0; k < sizeof fx / sizeof fx[0]; k++) {
        char src[256], exp[256], path[256], out[256], side[256];
        snprintf(src, sizeof src, "fixtures/%s", fx[k].name);
        snprintf(exp, sizeof exp, "fixtures/%s.expected", fx[k].name);
        snprintf(path, sizeof path, "/tmp/lgc_%s", fx[k].name);
        snprintf(out, sizeof out, "/tmp/lgc_%s.dump", fx[k].name);
        wipe_all(path);
        copy(src, path);
        snprintf(side, sizeof side, "%s.h0", src); if (exists(side)) { char d[256]; snprintf(d, sizeof d, "%s.h0", path); copy(side, d); }
        snprintf(side, sizeof side, "%s.h1", src); if (exists(side)) { char d[256]; snprintf(d, sizeof d, "%s.h1", path); copy(side, d); }
        tsdb_config_t c = {0};
        c.filepath = path; c.num_params = fx[k].np; c.param_names = fx[k].names;
        c.max_records = fx[k].maxrec; c.buffer_pool_size = 16 * 1024;
        c.alloc_strategy = TSDB_ALLOC_INTERNAL_RAM;
        c.segment_bytes = 1024;          // one-block segments: a conversion round per block
        tsdb_t *db = tsdb_open(&c);
        if (!db) { CHECK(0, fx[k].name); continue; }
        bool more = true; int steps = 0; esp_err_t e = ESP_OK;
        while (more && steps < 10000 && e == ESP_OK) { e = tsdb_maintain_h(db, &more); steps++; }
        char label[96];
        snprintf(label, sizeof label, "%s: converted (%d steps)", fx[k].name, steps);
        CHECK(e == ESP_OK && !more && !exists(path), label);
        dump(db, out);
        long la, lb; char *a = slurp(out, &la), *b = slurp(exp, &lb);
        snprintf(label, sizeof label, "%s: dump identical after conversion", fx[k].name);
        CHECK(a && b && la == lb && memcmp(a, b, la) == 0, label);
        free(a); free(b);
        tsdb_close_h(db);
        db = tsdb_open(&c);
        dump(db, out);
        a = slurp(out, &la); b = slurp(exp, &lb);
        snprintf(label, sizeof label, "%s: ... and after a reopen", fx[k].name);
        CHECK(a && b && la == lb && memcmp(a, b, la) == 0, label);
        free(a); free(b);
        char cv[300], h0[300];
        snprintf(cv, sizeof cv, "%s.cv", path); snprintf(h0, sizeof h0, "%s.h0", path);
        snprintf(label, sizeof label, "%s: no marker or sidecar left", fx[k].name);
        CHECK(!exists(cv) && !exists(h0), label);
        tsdb_close_h(db);
    }

    // Guard-capped device upgrading: free space is already below the reserve
    // when 3.0 writes for the first time. The first segment cannot be created
    // within the reserve, so the adopted file is evicted — the documented
    // caveat. Pinned here so a change in that policy is a deliberate one.
    printf("guard-capped upgrade\n");
    {
        const char *path = "/tmp/lg_guard.tsdb";
        wipe_all(path);
        copy("fixtures/wrapped.tsdb", path);
        const char *n3[] = {"soc", "vbat", "pload"};
        tsdb_config_t c = {0};
        c.filepath = path; c.num_params = 3; c.param_names = n3; c.max_records = 150;
        c.buffer_pool_size = 16 * 1024; c.alloc_strategy = TSDB_ALLOC_INTERNAL_RAM;
        c.free_space_cb = low_free; c.min_free_bytes = 100000;
        tsdb_t *db = tsdb_open(&c);
        tsdb_stats_t s; tsdb_get_stats_h(db, &s);
        CHECK(db && s.total_records == 150, "adopted with the guard configured");
        int16_t v[3] = {1, 2, 3};
        CHECK(tsdb_write_h(db, s.newest_timestamp + 10, v) == ESP_OK, "first write succeeds");
        tsdb_get_stats_h(db, &s);
        CHECK(!exists(path) && s.total_records == 1, "legacy file evicted to make room (documented)");
        CHECK(s.max_records == 150, "capacity latched at the former footprint, not one segment");
        for (int i = 0; i < 300; i++) { v[0] = (int16_t) i; tsdb_write_h(db, s.newest_timestamp + 10 * (i + 2), v); }
        tsdb_get_stats_h(db, &s);
        CHECK(s.total_records == 150 && s.max_records == 150, "window stays at the former capacity");
        tsdb_close_h(db);
    }

    // Schema ops refuse while a query is open on the handle.
    printf("open-query guard\n");
    {
        const char *path = "/tmp/lg_qguard.tsdb";
        wipe_all(path);
        copy("fixtures/wrapped.tsdb", path);
        const char *n3[] = {"soc", "vbat", "pload"};
        tsdb_config_t c = {0};
        c.filepath = path; c.num_params = 3; c.param_names = n3; c.max_records = 150;
        c.buffer_pool_size = 16 * 1024; c.alloc_strategy = TSDB_ALLOC_INTERNAL_RAM;
        tsdb_t *db = tsdb_open(&c);
        tsdb_query_t q; tsdb_query_init_h(db, &q, 0, UINT32_MAX, NULL, 0);
        CHECK(tsdb_clear_h(db) == ESP_ERR_INVALID_STATE, "clear refused while a query is open");
        CHECK(tsdb_rename_param_h(db, 0, "x") == ESP_ERR_INVALID_STATE, "rename refused while a query is open");
        uint32_t ts; int16_t rv[3]; int n = 0;
        while (tsdb_query_next(&q, &ts, rv) == ESP_OK) n++;
        tsdb_query_close(&q);
        CHECK(n == 150, "query unaffected");
        CHECK(tsdb_rename_param_h(db, 0, "x") == ESP_OK, "rename allowed after close");
        tsdb_close_h(db);
    }

    printf("\n%s (%d failed)\n", fails ? "*** FAIL ***" : "*** PASS ***", fails);
    return fails ? 1 : 0;
}
